int max(int[] array) {
    int max = array[0];                       // 3T
    for (int i = 1; i < array.length; i++) {  // T + 2nT
        if (array[i] > max) {                 // 2T(n-1)
            max = array[i];                   // 2T(n-1)
        }
    }
    return max;                               // T
}

boolean contains(int[] a, int x) {
    for (int i = 0; i < a.length; i++) {  // 2T
        if (x == a[i]) {                  // 2T
            return true;                  // T
        }
    }
    return false;
}

