boolean isPrime(int n) {
  for (int x = 2; x <= sqrt(n); x++) {
    if (n % x == 0) {
      return false;
    }
  }
  return true;
}

int sum(Node node) {
  if (node == null)
    return 0;
  return sum(node.left)
    + node.value
    + sum(node.right);
}

int fib(int n) {
  if (n <= 0) return 0;
  if (n == 1) return 1;
  return fib(n-1) + fib(n-2);
}

int factorial(int n) {
  if (n < 0) return -1;
  if (n == 0) return 1;
  return n * factorial(n-1);
}

int busquedaBinaria(const vector<int>& v, int objetivo) {
    int lo = 0, hi = (int)v.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == objetivo) return mid;
        else if (v[mid] < objetivo) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

class ArregloDinamico {
  int* datos;
  size_t tam, capacidad;
  long long costoTotal;
  void redimensionar(size_t nueva) {
    int* nuevos = new int[nueva];
    for (size_t i = 0; i < tam; ++i) {
      nuevos[i] = datos[i]; ++costoTotal;
    }
    delete[] datos; datos = nuevos;
    capacidad = nueva;
  }

void push_back(int valor) {
    if (tam == capacidad)
        redimensionar(capacidad * 2);
    datos[tam++] = valor; ++costoTotal;
}

